contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // This test checks that after calling Initialized(), further calls to SetMinSum revert (i.e., initialization makes setters unusable).
    function run(uint newMin) public payable {
        // Ensure we can call Initialized()
        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            initReverted = true;
        } else {
            initReverted = false;
        }

        // Now try to call SetMinSum; according to the contract logic, if Initialized() succeeded then SetMinSum should revert.
        bool setReverted;
        c.SetMinSum(newMin); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setReverted = true;
        } else {
            setReverted = false;
        }

        // General rule: if Initialized() did not revert then SetMinSum must revert; otherwise we make no claim.
        assert(initReverted || setReverted);
    }

    receive() external payable {}
}

